"Anyone remember why the sky is a portal?":"Kas keegi mäletab, miks taevas on portaal?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"Räägitakse, et kui šahti hüpata, tuled välja vaenlase juures. Ei hakka proovima.",
"The Swarm painted their visors red again. Show-offs.":"Sülem värvis oma visiirid taas punaseks. Uhkeldajad.",
"Ore, ore… when do we get some oil?":"Maak, maak… millal õli antakse?",
"I dreamt I was a toaster. It was peaceful.":"Nägin unes, et olin röster. Oli rahulik.",
"Quiet. Too quiet.":"Vaikne. Liiga vaikne.",
"See that? Our base is above the Swarm base again. Portals, man.":"Nägite? Sülemi baasi kohal on taas meie baas. Portaalid, mees.",
"Diman, if you're reading this — we need a vacation.":"Diman, kui sa seda loed — me vajame puhkust.",
