"Battle loaded: {0}":"Lahing laaditud: {0}",
"Autosaved":"Automaatselt salvestatud",
"robot war · the sky is a portal":"robotite sõda · taevas on portaal",
"Welcome to the meteor! You are a Consortium combat robot. Look around with the mouse and walk with WASD.":"Tere tulemast meteoriidile! Sa oled Konsortsiumi lahinguroboot. Vaata hiirega ringi ja liigu: WASD.",
"Jetpack: tap Shift to hop, hold Shift to fly. Energy recharges on the ground.":"Jetpack: puuduta Shift — hüpe, hoia Shift — lend. Energia taastub maas.",
"Fire — LMB. Aim — RMB: more accurate, with zoom. Fire a few shots.":"Tulista — hiire vasak nupp. Sihik — hiire parem nupp: täpsem ja suurendusega. Tee mõni lask.",
"Reload — R. Bullets hit hardest at medium range, 20–50 meters.":"Taaslaadimine — R. Kuulid löövad kõige tugevamini keskmisel kaugusel, 20–50 meetrit.",
"Rocket — Q. For tanks and buildings. Fire a rocket.":"Rakett — Q. Tankide ja hoonete vastu. Lase rakett välja.",
"At the top is the strategist's order. Run along the green arrows: you sprint on the route. Capture the point — stay near the beacon.":"Üleval on strateegi ülesanne. Jookse mööda rohelisi nooli: marsruudil oled sprindis. Vallutamiseks seisa majaka lähedal.",
"Your squad has your back: their portraits and health are on the left. If they fall behind, they will ask you to wait.":"Sinu salk katab sind: vasakul on nende portreed ja tervis. Kui salk jääb maha, paluvad võitlejad oodata.",
"{0} — quick unit switch without leaving the battle: jump into the squad or tank closest to the fight. Try it.":"{0} — kiire üksuse vahetus lahingust lahkumata: hüppa lahingule lähimasse salka või tanki. Proovi.",
"Next to a tank or turret press E to take control. Or just carry on.":"Tanki või kahurtorni kõrval vajuta E, et neid juhtida. Või mine lihtsalt edasi.",
"Now strategy. Tap \"◩ Strategy\" at the top right — a top view of the battlefield.":"Nüüd strateegia. Puuduta paremal üleval «◩ Strateegia» — lahinguvälja pealtvaade.",
"Now strategy. Press {0} (or \"◩ Strategy\" at the top left) — a top view of the battlefield.":"Nüüd strateegia. Vajuta {0} (või vasakul üleval «◩ Strateegia») — lahinguvälja pealtvaade.",
"In strategy the Curator helps you: the box at the top says what to do, a frame shows the button, a ring marks the spot on the map. Complete three of its tips.":"Strateegias aitab sind Juhendaja: ülemine aken ütleb, mida teha, raam näitab nuppu, rõngas märgib koha kaardil. Täida kolm tema nõuannet.",
"Select a squad and tap the green \"▶ Possess\" button — back into battle as that trooper. While you shoot, the AI strategist runs the army.":"Vali salk ja puuduta rohelist nuppu «▶ Haldama» — tagasi lahingusse selle sõduri rollis. Kuni sina tulistad, juhib armeed AI-strateeg.",
"Select a squad and press {0} or the green \"▶ Possess\" — back into battle as that trooper (nothing selected — your own). While you shoot, the AI strategist runs the army.":"Vali salk ja vajuta {0} või roheline «▶ Haldama» — tagasi lahingusse selle sõduri rollis (kui midagi pole valitud, siis oma robotina). Kuni sina tulistad, juhib armeed AI-strateeg.",
"Training complete! The Swarm is launching its offensive. Good luck, trooper!":"Väljaõpe läbitud! Sülem alustab pealetungi. Edu, sõdur!",
