"The heavy MG is a reward the strategist hands out for completed orders.":"Raskekuulipilduja on preemia, mille strateeg annab täidetud käskude eest.",
"{0} unlocks at rank \"{1}\". XP comes from kills, captures and strategist orders (×2–×3).":"{0} avaneb auastmel «{1}». Kogemust annavad tapmised, vallutused ja strateegi käsud (×2–×3).",
"Left thumb — move, right thumb — look. Red button — fire.":"Vasak pöial — liikumine, parem — vaade. Punane nupp — tuli.",
"⇑ — jetpack: tap to hop, hold to fly. ◎ — aim.":"⇑ — jetpack: puudutus annab hüppe, hoia all lendamiseks. ◎ — sihik.",
"In the air, ⤓ is the jet brake.":"Õhus on ⤓ jetpacki pidur.",
"Move and shoot: mouse to look, LMB to fire.":"Liigu ja tulista: hiir — vaade, hiire vasak nupp — tuli.",
"At the top is the AI strategist's order. Follow it: ×2 and ×3 XP, and completed orders can earn rewards. The green marker and chevrons lead the way.":"Üleval on AI-strateegi käsk. Täida see: kogemus ×2 ja ×3, täidetud käskude eest võib saada preemiaid. Roheline märk ja nooled juhivad sihile.",
"Shift — jump pack: tap to hop, hold to fly. RMB — aim.":"Shift — jetpack: puudutus annab hüppe, hoia all lendamiseks. Hiire parem nupp — sihik.",
"In the air, C is the jet brake. Stop, turn with the mouse and thrust again.":"Õhus on C jetpacki pidur. Pidurda, pööra end hiirega ja anna uuesti tõuget.",
"Enemy vehicle or structure nearby. A rocket is best against them.":"Läheduses on vaenlase tehnika või ehitis. Nende vastu on parim rakett.",
"Enemies are bunched up — throw a grenade.":"Vaenlased on kuhjunud — viska granaat.",
"Lots of hostiles — trigger Reflex: time slows down and you can pick them off.":"Vaenlasi on palju — lülita sisse refleks: aeg aeglustub ja jõuad kõik maha võtta.",
"Aim at the enemy cluster and call in a strike.":"Sihi vaenlaste kogunemisele ja kutsu löök.",
"Targets are far — the railgun is stronger at long range.":"Sihtmärgid on kaugel — rööpaanon on kaugel tugevam.",
"You have a temporary heavy MG — use it before it is recalled.":"Sul on ajutine raskekuulipilduja — kasuta seda, enne kui see tagasi kutsutakse.",
"Parkour: C while running — slide, jump at a ledge — climb it, jump next to a wall in the air — wall-jump.":"Parkuur: jooksul C — libisemine, hüpe astangu juures — ronimine, hüpe õhus seina kõrval — seinahüpe.",
"Bullets hit hardest at 20–50 m. Point-blank and long range are much weaker — for enemies too.":"Kuulid löövad kõige kõvemini 20–50 m kauguselt. Täitsa lähedalt ja kaugelt on need palju nõrgemad — vaenlastel samuti.",
"Your robot is badly damaged. Get out of the fire — armor self-repairs out of combat.":"Sinu robot on tugevasti kahjustatud. Mine tule alt ära — soomus parandab end väljaspool lahingut ise.",
"One of our tanks is close. Walk up and press E to take control.":"Üks meie tankidest on lähedal. Mine ligi ja vajuta E, et seda juhtida.",
"Man the turret — press E next to it.":"Võta kahurtorn — E selle kõrval.",
"It is quiet here. Switch to a squad or vehicle closer to the fight.":"Siin on vaikne. Lülitu salgale või tehnikale lahingule lähemal.",
"Reload early while no enemies are around.":"Lae relv varakult uuesti, kuni vaenlasi pole.",
"Sprint right along the strategist's green chevrons — you run faster on his route.":"Sprindi otse piki strateegi rohelisi nooli — tema marsruudil jooksed kiiremini.",
"\"◩ Strategy\" button — top view: build the base, order troops, command squads.":"Nupp «◩ Strateegia» — pealtvaade: ehita baas, telli vägesid, juhi salku.",
"Strategy mode: build the base, order troops, call strikes and command squads. The same key there possesses the selected unit.":"Strateegia režiim: ehita baas, telli vägesid, kutsu lööke ja juhi salku. Sama klahv seal haldab valitud üksust.",
"Want full command? Turn off the AI strategist — then you give the orders.":"Tahad ise juhtida? Lülita AI-strateeg välja — siis annad käsud sina.",
"Third-person view — to see your robot.":"Kolmanda isiku vaade — et näha oma robotit.",
"Tank: {0} — barrage at your aim point, {1} — smoke screen, {2} — overdrive. {3} — back to infantry.":"Tank: {0} — pauk sihtpunkti, {1} — suitsukate, {2} — forsaaž. {3} — tagasi jalaväkke.",
"Plenty of targets — fire a barrage.":"Sihtmärke on palju — tee pauk.",
"Drone: {0}/{1} — up/down, LMB — fire, {2} — ram your aim point.":"Droon: {0}/{1} — kõrgemale/madalamale, hiire vasak nupp — tuli, {2} — ramm sihtpunkti.",
"Select a squad — LMB, drag a box or a card on the left. RMB on the ground — attack-move ⚔, on an enemy — attack, on a point — capture.":"Vali salk — hiire vasaknupuga, raamiga või kaardiga vasakul. Hiire parem nupp maapinnal — ründeliikumine ⚔, vaenlasel — rünnak, punktil — vallutus.",
"Squads have abilities: grenades, jet leap, suppression, repair. Tanks: barrage, smoke, overdrive.":"Salkadel on oskused: granaadid, hüpe rakettseljakotiga, mahasurumine, remont. Tankidel: tulemürsk, suitsuvarje, ülekiirendus.",
"Plenty of ore — select the HQ or a factory and order troops in its panel on the right.":"Maaki on palju — vali staap või tehas ja telli vägesid selle paneelilt paremal.",
"Command points are piling up — \"Powers\" tab: recon, artillery, squad drop pod, orbital strike.":"Käsupunkte koguneb — vahekaart «Võimed»: luure, suurtükitule löök, salga kapsel, orbitaalne löök.",
"Only builders construct buildings: select a builder (button in the Build tab or a building key), then click the spot. An extractor (C) on a glowing vein — more ore.":"Hooneid ehitavad ainult insenerid: vali insener (nupp vahekaardil «Ehitus» või hoone klahv), siis klõpsa kohale. Ekstraktor (C) helendaval soonel — rohkem maaki.",
"Click \"ORE\" at the top left — where ore comes from and how to boost income.":"Klõpsa vasakul üleval «MAAK» — kust maak tuleb ja kuidas tulu kasvatada.",
"Ctrl+1…9 — save a group, 1…9 — select it, double-tap — jump the camera.":"Ctrl+1…9 — salvesta rühm, 1…9 — vali see, topeltvajutus — kaamera selle juurde.",
"Select a unit and tap the green \"▶ Possess\" below (or double tap) to fight yourself. \"◩ Strategy\" brings you back.":"Vali üksus ja puuduta all rohelist «▶ Haldama» (või topeltpuudutus) — võitled ise. «◩ Strateegia» toob tagasi.",
"Select a unit and press the green \"▶ Possess\" below or {0} (or double-click) to fight yourself. In battle {1} brings you back.":"Vali üksus ja vajuta all rohelist «▶ Haldama» või {0} (või topeltklõps) — võitled ise. Lahingus toob {1} strateegiasse tagasi.",
"Grey buttons can be pressed too: you will see what is missing, how long to wait and how to fix it.":"Halle nuppe võib ka vajutada: näitame, mis puudub, kui kaua oodata ja kuidas parandada.",
"RMB on the ground — rally point for this building's new troops.":"Hiire parem nupp maapinnal — selle hoone uute vägede kogunemispunkt.",
"RMB — attack-move ⚔: they stop to fight enemies they meet, then continue. Double RMB — march »: run without stopping, firing on the move. Hold/Retreat — \"More orders ▾\".":"Hiire parem nupp — ründeliikumine ⚔: kohtavad vaenlast, peatuvad ja võitlevad, siis lähevad edasi. Topelt-parem nupp — marss »: jooksevad peatumata ja tulistavad käigu pealt. Hoia/Taganeda — «Veel käske ▾».",
"Camera: drag with a finger, two fingers — zoom and rotate, drag on the minimap too.":"Kaamera: lohista sõrmega, kahe sõrmega — suum ja pööre, ka minikaarti saab lohistada.",
"Camera: WASD and screen edges, Q/E rotate, wheel zoom (to cursor), MMB orbit, minimap — click or drag, Space — to the latest alert.":"Kaamera: WASD ja ekraani servad, Q/E — pööre, ratas — suum (kursorini), hiire keskmine nupp — orbiit, minikaart — klõps või lohistamine, tühik — viimase häireni.",
