"New in v6.3":"Uus versioonis v6.3",
"New in v6.2":"Uus versioonis v6.2",
"New ore look: veins are glowing emerald faceted crystals on black basalt with sparks and green haze; the extractor is a hex pedestal with a honeycomb dome and a lattice tower topped by a green beacon (stripe and pennant in team colour)":"Maagi uus välimus: maagisooned on helendavad smaragdrohelised lihvitud kristallid mustal basaldil, sädemete ja rohelise hägusega; ekstraktor on kuusnurkne alus, kärgkuppel ja võretorn rohelise majakatulega (triip ja vimpel — tiimi värvi)",
"New in v6.1":"Uus versioonis v6.1",
"Preferred class like in Battlefield (U, numbers after death): you respawn into it when available":"Eelistatud klass nagu Battlefieldis (U, numbrid pärast hukkumist): sünnid sellesse uuesti, kui see on saadaval",
"Vehicles in first person (V — outside/cockpit); gentle aim assist — in Settings":"Tehnika esimese isiku vaates (V — väljastpoolt/kabiinist); õrn sihtimisabi — Seadetes",
"Easy exit from the core: Space — to the shaft, B — capsule to the surface; ability effects reset on death":"Tuumast on nüüd lihtne välja pääseda: tühik — šahti juurde, B — kapsel pinnale; oskuste mõjud lähtestuvad hukkumisel",
"Endless progression: generals and Marshal ★, career levels, weapon mastery and attachments, medals, daily contracts — Career screen":"Lõputu areng: kindralid ja Marssal ★, karjääri tasemed, relvameisterlikkus ja lisad, medalid, päevalepingud — ekraan \"Karjäär\"",
"Strategy: smooth wheel zoom, unit icons and labels (Alt — all), Troops / Buildings panel on the left":"Strateegia: sujuv ratta suum, üksuste ikoonid ja sildid (Alt — kõik), vasakul paneel \"Väed / Hooned\"",
"RMB — attack-move, double RMB — march firing on the move; rare orders in \"More orders ▾\"; no duplicate buttons":"hiire parem nupp — ründa liikudes, 2× hiire parem nupp — marss tulistades käigu pealt; harvad käsud — menüüs \"Veel käske ▾\"; nupud ei dubleeru",
"New in v6":"Uut versioonis v6",
"Shooter-grade guns: hitscan bullets, 720 RPM rifle, MG, recoil, RMB aim, magazines and R reload, hit markers":"Laskurimängu moodi relvad: silmapilksed kuulid, püssitulekiirus 720 lasku/min, kuulipilduja, tagasilöök, sihik hiire parema nupuga, salved ja laadimine R, tabamusmärgid",
"Heavier gravity, responsive jetpack, dash on Z or double jet in the air; the weapon no longer flies along when switching units":"Raskem gravitatsioon, tundlik jetpack, hoog Z-ga või 2× jetpack õhus; üksust vahetades relv enam kaasa ei lenda",
"Builders: select a builder, pick a building, place a blueprint; extractors on ore veins; click \"ORE\" to see income and how to boost it":"Insenerid: vali insener, vali hoone, aseta joonis; ekstraktorid maagisoontele; klõpsa «MAAGIL», et näha sissetulekut ja kuidas seda kiirendada",
"Grey buttons explain why and offer a fix; bigger buttons, \"In progress\" strip, \"▶ Possess\", Tab is the one mode key":"Hallid nupud selgitavad põhjust ja pakuvad lahendust; suuremad nupud, riba «Töös», «▶ Võta üle», Tab on ainus režiimiklahv",
"Strategy camera without jumps or flips, zoom to cursor, draggable minimap":"Strateegia kaamera ilma hüpete ja ümberpöördeteta, suum kursorini, minikaarti saab lohistada",
"New vehicles: Jackal raider, Grad MLRS (homing rockets), Hammer mortar; the Swarm gets Wasp, Hive, Trebuchet":"Uus tehnika: «Jackal», «Grad» (isesihtivad raketid), mört «Hammer»; Sülemil «Wasp», «Hive», «Trebuchet»",
"The strategist keeps orders and stops voice spam; fights come to you; B — redeploy, Shift+B — into the fight; compass, H — which target":"Strateeg säilitab käsud ja ei risusta häält; lahingud tulevad sinu juurde; B — ümberpaigutus, Shift+B — lahingusse; kompass, H — milline siht",
"Free play (K) and going solo (J), F2 presets; Esc pauses and resumes; saves: slots, export and import":"Vabamäng (K) ja üksi tegutsemine (J), F2 — eelseaded; Esc — paus ja jätkamine; salvestused: pesad, eksport ja import",
"New in v5.3":"Uut v5.3-s",
"Flight: stronger gravity far from the meteor, C in the air brakes, thrust steers sharper; no more getting stuck in the portal":"Lend: tugevam gravitatsioon meteoriidist kaugel, C õhus — pidur, tõukejõud juhib teravamalt; portaali enam kinni ei jää",
"New in v5":"Uut v5-s",
