"Side tasks, sky shortcut, first-expedition habitats with supplies, crystals, crater ice, dust storms":"Kõrvalülesanded, lühitee taeva kaudu, esimese ekspeditsiooni moodulid varudega, kristallid, jää kraatrites, tolmutormid",
