"RMB on a button — cancel · RMB on the ground — rally point":"Hiire parem nupp nupul — tühista · hiire parem nupp maal — koondumispunkt",
"Curator":"Kuraator",
"Guides you during play: arrows to buttons and marks on the map. Turn it off any time (also in Settings).":"Annab mängu käigus nõu, mida ja kus teha: nooled nuppudele ja märgid kaardil. Võid selle igal ajal välja lülitada (ka Seadetes).",
"queue {0}/5":"järjekord {0}/5",
"Select the HQ and train a builder (50 ore) — click to open the HQ panel":"Vali staap ja telli insener (50 maaki) — klõps avab staabi paneeli",
"Builders are trained only at the HQ: select the HQ (click it or F2) — its production panel opens on the right. Same for the mech factory, drone hub, airdock and outpost":"Insenere tellitakse ainult staabis: vali staap (klõps sellel või F2) — paremal avaneb selle tootmispaneel. Sama kehtib mehhitehase, droonikeskuse, lennudokki ja eelpostiga",
"The Build tab opens when a builder is selected; a \"Select nearest builder\" button; Z X C V B N K pick a builder automatically":"Vahekaart \"Ehitus\" avaneb, kui insener on valitud; nupp \"Vali lähim insener\"; klahvid Z X C V B N K valivad inseneri ise",
"The Curator replaces the strategy tutorial: it suggests what to do as you play, points at the button and marks the map; turn it off on the panel or in Settings":"Juhendaja asendab strateegia õpetuse: annab mängu käigus nõu, mida teha, näitab noolega nuppu ja märgib kaardil; lülitub välja paneelil või Seadetes",
"Developer mode (main menu): unlimited ore, everything unlocked, instant build, the Arsenal — any weapon, class, vehicle, target dummies; your career is untouched":"Arendajarežiim (peamenüü): piiramatu maak, kõik avatud, hetkeehitus, Arsenal — mis tahes relv, klass, sõiduk, märklaudnukud; sinu karjäär ei muutu",
"Phone: shooter buttons no longer cover the crosshair or weapon, strategy panels collapse, bigger buttons, a clear \"Strategy ⇄ Battle\" switch":"Telefon: laskurinupud ei kata sihikut ega relva, strateegiapaneelid kerivad kokku, suuremad nupud, selge üleminek \"Strateegia ⇄ Lahing\"",
"Combined build: the v6.2 ore-vein crystals and extractors + grenades with a throw arc":"Koondversioon: v6.2 maagisoonte uued kristallid ja ekstraktorid + granaadid viskekaarega",
"New in v6.4":"Uut versioonis v6.4",
"Curator on: I will suggest what to do":"Juhendaja sees: annan nõu, mida teha",
