"BUILDER":"INSENER",
"VEIN ⛏":"SOON ⛏",
"ENEMY":"VAENLANE",
"Select a builder: the \"⚒ Select nearest builder\" or \"⚒ Builder\" button.":"Vali insener: nupp \"⚒ Vali lähim insener\" või \"⚒ Insener\".",
"Select a builder: \"⚒ Select nearest builder\" on the right or click one.":"Vali insener: nupp \"⚒ Vali lähim insener\" paremal või klõpsa temal.",
"Tap the marked vein ⛏ (glowing crystals), then \"✔ Build\". Mark off-screen — tap it to fly the camera there.":"Puuduta märgitud soont ⛏ (helendavad kristallid), siis \"✔ Ehita\". Märk on ekraani taga — puuduta seda, kaamera lendab sinna.",
"Click the marked vein ⛏ — the glowing crystals (RMB/Esc — cancel). Mark off-screen — click it to fly the camera there.":"Klõpsa märgitud soonel ⛏ — helendavatel kristallidel (hiire parem nupp/Esc — tühista). Märk on ekraani taga — klõpsa sellel, kaamera lendab sinna.",
"Tap a spot for the {0}, then \"✔ Build\".":"Puuduta kohta hoonele \"{0}\", siis \"✔ Ehita\".",
"Click a spot for the {0} (RMB/Esc — cancel).":"Klõpsa kohal hoonele \"{0}\" (hiire parem nupp/Esc — tühista).",
"I am the Curator: I highlight the button and the spot on the map. \"✕\" turns me off.":"Mina olen Juhendaja: tõstan esile õige nupu ja koha kaardil. \"✕\" — lülita välja.",
"I am the Curator. I will suggest what to do as you play, highlighting the button and the spot on the map. Turn me off with \"✕\" here or the \"Curator\" button at the bottom right.":"Mina olen Juhendaja. Annan lahingu käigus nõu, mida teha: tõstan esile nupu ja koha kaardil. Väljalülitamiseks \"✕\" siin või nupp \"Juhendaja\" all paremal.",
"The Swarm is at the base! \"All army\", then long-tap the enemies. A turret at the base helps too.":"Sülem on baasi juures! \"Kogu armee\", siis pikk puudutus vaenlastel. Baasi kahurtorn aitab samuti.",
"The Swarm is at the base! Select troops (box or Ctrl+A) and RMB the enemies. A turret (Z) helps too.":"Sülem on baasi juures! Vali väed (raamiga või Ctrl+A) ja hiire parem nupp vaenlastel. Baasi kahurtorn (Z) aitab samuti.",
"Camera: drag the map with a finger, two fingers — zoom and rotate. Move the camera.":"Kaamera: lohista kaarti sõrmega, kahe sõrmega — suum ja pööre. Liiguta kaamerat.",
"Camera: WASD or screen edges, wheel — height, Q/E — rotate. Move the camera.":"Kaamera: WASD või ekraani servad, ratas — kõrgus, Q/E — pööre. Liiguta kaamerat.",
"No builders — and nothing gets built without them. Select the HQ — click it or the \"⌂ HQ\" button.":"Insenere pole ja ilma nendeta ei ehita ühtegi hoonet. Vali staap — klõpsa sellel või nupul \"⌂ Staap\".",
"Order a builder — the \"⚒ Builder\" button in the HQ panel (50 ore).":"Telli insener — nupp \"⚒ Insener\" staabi paneelil (50 maaki).",
"We need ore — let us put an extractor on an ore vein.":"Vaja on maaki — paneme maagisoonele ekstraktori.",
"Press \"Extractor\" (C) and place it on the glowing crystals of the vein — I marked it ⛏.":"Vajuta \"Ekstraktor\" (C) ja aseta soone helendavatele kristallidele — märkisin selle ⛏.",
"Few troops. Select the HQ — squads are ordered there.":"Vähe väge. Vali staap — salku tellitakse seal.",
"Order an \"Assault squad\" in the HQ panel.":"Telli staabi paneelil \"Ründesalk\".",
"Points give ore. Select a squad — tap it or the \"◈ Squad\" button on the right.":"Punktid annavad maaki. Vali salk — puuduta seda või nuppu \"◈ Salk\" paremal.",
"Points give ore. Select a squad — tap it or the \"◆ Army\" card at the top.":"Punktid annavad maaki. Vali salk — puuduta seda või kaarti \"◆ Armee\" üleval.",
"Points give ore. Select a squad — click it or its card in the \"◆ Army\" panel on the left.":"Punktid annavad maaki. Vali salk — klõpsa sellel või selle kaardil paneelil \"◆ Armee\" vasakul.",
"Long-tap point {0} — the squad goes to capture it.":"Pikk puudutus punktil {0} — salk läheb vallutama.",
"RMB on point {0} — the squad goes to capture it.":"Hiire parem nupp punktil {0} — salk läheb seda vallutama.",
"POINT ":"PUNKT ",
"The base is under attack — let us build a turret.":"Baasi rünnatakse — paneme kahurtorni.",
"Press \"Turret\" (Z) and place it at the base, facing the enemy.":"Vajuta \"Kahurtorn\" (Z) ja aseta baasi juurde, näoga vaenlase poole.",
"Enough ore for a mech factory — it makes tanks and vehicles.":"Maaki jätkub mehhitehaseks — seal tehakse tanke ja sõidukeid.",
"Press \"Mech factory\" (B) and place it at the base (a flat spot inside the dashed ring).":"Vajuta \"Mehhitehas\" (B) ja aseta baasi (tasane koht punktiirringi sees).",
"{0} is idle — select it and give an order: {1} a point or an enemy.":"{0} seisab jõude — vali ja anna käsk: {1} punktil või vaenlasel.",
"The mech factory is ready. Select it to order a tank.":"Mehhitehas on valmis. Vali see — telline tanki.",
"Order a \"Tank\" in the factory panel.":"Telli tehase paneelil \"Tank\".",
"More extractors — more ore. There is a free vein nearby.":"Rohkem ekstraktoreid — rohkem maaki. Lähedal on vaba soon.",
"\"Extractor\" (C) on the marked vein ⛏.":"\"Ekstraktor\" (C) märgitud soonele ⛏.",
"Pick a power and click an enemy cluster.":"Vali löök ja klõpsa vaenlaste kogunemisel.",
"Command points are piling up — the \"✺ Powers\" tab: artillery, recon, drop pod.":"Käsupunkte koguneb — vahekaart \"✺ Löögid\": suurtükitule löök, luure, kapsel.",
"Low on ore? Tap \"ORE\" at the top — see where income comes from and how to boost it.":"Maaki vähe? Puuduta üleval \"MAAK\" — näitan, kust tulu tuleb ja kuidas seda kiirendada.",
"Want to fight yourself? Select a squad and press \"▶ Possess\".":"Tahad ise võidelda? Vali salk ja vajuta \"▶ Võta üle\".",
