"The model follows the meteor surface normal, turns its torso to aim and holds the machine gun; far away the animation updates less often to keep FPS":"Mudel seisab meteoriidi pinna normaali suunas, pöörab keha sihi järgi ja hoiab kuulipildujat käes; kaugel uuendatakse animatsiooni harvemini — FPS ei lange",
