"{0} is online":"{0} on valmis",
"The HQ is destroyed":"Staap on hävitatud",
"The HQ is already building an upgrade":"Staap ehitab juba täiendust",
"HQ: {0} ready":"Staap: {0} valmis",
"HQ: {0} online":"Staap: {0} töötab",
"Intel: the Swarm HQ got \"{0}\"":"Luure: Sülemi staap sai \"{0}\"",
"Point {0}: orbit is dropping a pod — a squad{1}":"Punkt {0}: orbiit langetab kapsli — salk{1}",
"Pod on point {0}: {1}{2}{3}. The builder can place an outpost (V) and pick an upgrade branch.":"Kapsel punktis {0}: {1}{2}{3}. Insener saab püstitada eelposti (V) ja valida täienduste haru.",
"HQ radar: every enemy is visible for 6 s":"Staabi radar: kõik vaenlased on 6 s näha",
"HQ upgrades":"Staabi täiendused",
"Built":"Ehitatud",
"Building — click to cancel (refund)":"Ehitamisel — klõps: tühista (maak tagastatakse)",
"Outpost upgrades":"Eelposti täiendused",
"point":"punkt",
"Pick a branch — every point gets its own speciality:":"Vali haru — igal punktil on oma eriala:",
"Building — click to cancel":"Ehitamisel — klõps: tühista",
"A builder near the outpost (30 m) does the upgrade.":"Täienduse ehitab insener eelposti lähedal (30 m).",
"Send a builder":"Saada insener",
"Builders nearby":"Insenere lähedal",
"{0} is heading to the outpost":"{0} suundub eelposti juurde",
"From the very start your base has the whole army, one of each: sky troopers, lone heavy gunner, sniper, scout, drone, raider, MLRS, mortar (plus assault squads and a tank) — possess anyone right away":"Lahingu algusest peale seisab sinu baasis kogu armee, igaüks ühe korra: langevarjurid, üksik raskerelvur, snaiper, luuraja, droon, rüüstaja, reaktiivsalvokahur, mört (ning ründesalgad ja tank) — võta kohe kontrolli alla igaüks",
"\"Custom order\" for possession (pause menu, ☰ on the phone): each class has a number, 1 is the top; ▲▼ change it, ✕ means never. After death and on X you get the unit closest to the fight in that order":"Haldamise \"Oma järjekord\" (pausimenüü, telefonis ☰): igal klassil on number, 1 on peamine; ▲▼ muudavad, ✕ tähendab mitte kunagi. Pärast surma ja X-iga võetakse selle järjekorra järgi lahingule lähim üksus",
"Bots are no longer snipers: they miss at range, on the move, against runners and targets in cover; bullets whizz past you and kick up dirt and cover nearby. Explosions knock you down: flinch, to one knee, off your feet and back up":"Botid pole enam snaiprid: nad eksivad kaugelt, liikvel olles, jooksjate ja varjus olijate pihta; kuulid vilistavad sust mööda ning lõhuvad mulda ja varju lähedal. Plahvatused paiskavad pikali: võpatus, põlvili, jalust maha ja tagasi üles",
"Capture a point and a pod drops a squad and a builder. An outpost on the point upgrades along one branch: defence (MG bunker → heavy bunker with AT gun), support (repair drones → force-field dome), recon (radio scanner → sniper & spotter tower)":"Vallutad punkti ja kapsel toob salga ning inseneri. Punktil olev eelpost areneb ühte haru pidi: kaitse (punker → raske punker tankitõrjekahuriga), tugi (remondidroonid → jõuvälja kuppel), luure (raadioskanner → snaiprutorn)",
"The HQ upgrades too: armour plating, defence turrets, faster orbital drop, +25% income, global radar, comms array (+command points). The AI does the same":"Ka staap areneb: soomusplaadid, kahurtornid, kiirem orbitaalne langetus, sissetulek +25%, globaalne radar, sideantennid (+käsupunktid). Tehisaru teeb sama",
"New in v7.0":"Uut versioonis v7.0",
"Your base has one of every unit and vehicle: sky troopers, sniper, scout, drone, raider, MLRS, mortar. Select any and {0} — try them before you even build.":"Baasis on igat tüüpi üksus ja masin ühe korra: langevarjurid, snaiper, luuraja, droon, rüüstaja, reaktiivsalvokahur, mört. Vali ükskõik kes ja {0} — proovi neid enne ehitamist.",
"POSSESS":"HALDA",
"Point {0}: a builder landed with the pod. Select it and place an \"Outpost\"{1} by the point — then pick an upgrade branch.":"Punkt {0}: kapslist maandus insener. Vali ta ja püstita punkti juurde \"Eelpost\"{1} — seejärel vali täienduste haru.",
"OUTPOST":"EELPOST",
"The outpost is ready — select it and pick a branch: ⛨ Defence (MG bunker, AT bunker), ✚ Support (repair drones, force-field dome) or ◎ Recon (scanner, sniper tower). A builder nearby does the work.":"Eelpost on valmis — vali see ja vali haru: ⛨ Kaitse (punker, tankitõrjepunker), ✚ Tugi (remondidroonid, jõuvälja kuppel) või ◎ Luure (skanner, snaiprutorn). Ehitab lähedal olev insener.",
"UPGRADE":"TÄIENDA",
"The HQ is a \"super point\": select it{0} — armour, turrets, faster drops, +25% income, radar, comms.":"Staap on \"superpunkt\": vali see{0} — soomus, kahurtornid, kiirem langetus, sissetulek +25%, radar, side.",
"☰ → \"Possession\": turn on \"Custom order\" and choose who you take after death — #1, #2… ✕ means never.":"☰ → \"Haldamine\": lülita sisse \"Oma järjekord\" ja vali, keda pärast surma hallata — nr 1, nr 2… ✕ tähendab mitte kunagi.",
"Esc → pause → \"Custom order\": choose who you take after death and on X — #1, #2… ✕ means never.":"Esc → paus → \"Oma järjekord\": vali, keda pärast surma ja X-iga hallata — nr 1, nr 2… ✕ tähendab mitte kunagi.",
