"Minimap":"Minikaart",
"Build: Barracks":"Ehitus: Kasarmu",
"Under construction":"Hoone ehitatakse",
"Production":"Tootmine",
"Mining ore":"Maagi kaevandamine",
"training complete":"väljaõpe läbitud",
"Tap \"Aim\" to zoom in. Tap again to zoom out.":"Puuduta «Sihik» — suum. Uus puudutus — tagasi.",
"Your squad follows you. Open ☰ → \"Pause\" → the \"Squad with me\" tile — it becomes \"Going solo\".":"Salk järgneb sulle. Ava ☰ → «Paus» → plaat «Salk minuga» — saab «Tegutsen üksi».",
"The builder is selected — tap \"◆ Mine crystals\" on its card below (or tap the green crystals).":"Insener on valitud — puuduta tema kaardil all «◆ Kaeva kristalle» (või puuduta rohelisi kristalle).",
"Training complete!":"Väljaõpe läbitud!",
"steps":"sammu",
"You can build a base, order troops, command and jump into battle. Next — a real match: the Curator will help as you play.":"Oskad ehitada baasi, tellida vägesid, komandeerida ja lahingusse hüpata. Edasi — päris mäng: Kuraator aitab mängu käigus.",
"You can move, fly, shoot, take cover and command your squad. Next — a real match.":"Oskad liikuda, lennata, tulistada, varjuda ja salka juhtida. Edasi — päris mäng.",
"Real battle":"Päris lahing",
"Again":"Veel kord",
"done":"läbitud",
"you are on PC: keyboard and mouse":"sul on arvuti: klaviatuur ja hiir",
"you are on a phone: touch screen":"sul on telefon: puuteekraan",
"A safe sandbox: enemies are still dummies, nobody shoots at you. A step counts only when you actually do the action.":"Turvaline liivakast: vaenlased on liikumatud mannekeenid, keegi sind ei tulista. Samm loetakse alles siis, kui teed toimingu ise.",
"Show others (training for the other device)":"Näita teisi (väljaõpe teisele seadmele)",
"Old training (v7.1)":"Vana väljaõpe (v7.1)",
"Back to the normal device mode":"Tagasi seadme tavarežiimi",
"Training for the other device reloads the page in its mode (PC — mouse and keyboard, phone — touch; on a PC you can test touch in Chrome: F12 → phone icon).":"Väljaõpe teisele seadmele laadib lehe uuesti selle režiimis (arvuti — hiir ja klaviatuur, telefon — puutega; arvutis saab puudet testida Chrome'is: F12 → telefoni ikoon).",
"Training ×4: separate step-by-step \"Strategy\" and \"Shooter\" lessons for PC and for phone. A safe sandbox with dummies, the right button highlighted, arrows, animated keys, mouse and gestures; a step counts only for the real action, \"repeat step\", progress at the top and a reward at the end":"Väljaõpe ×4: eraldi samm-sammulised õppetunnid «Strateegia» ja «Laskur» arvutile ja telefonile. Turvaline liivakast mannekeenidega, õige nupu esiletõst, nooled, animeeritud klahvid, hiir ja žestid; samm loetakse ainult päris tegevuse eest, «korda sammu», edenemine ülal ja auhind lõpus",
"The Training menu shows the lessons for your device; \"Show others\" — all four on any device; the \"Old training (v7.1)\" is still there":"Menüü «Väljaõpe» näitab su seadme õppetunde; «Näita teisi» — kõiki nelja igal seadmel; «Vana väljaõpe (v7.1)» on alles",
"New in v7.2":"Uus versioonis v7.2",
"NEW IN v7.2":"UUS VERSIOONIS v7.2",
"No grenades left":"Granaadid on otsas",
"Rocket and grenade recharging · {0} s":"Rakett ja granaat laevad · {0} s",
"Left — move, right — look · tap an enemy — rocket / grenade · 2 taps — reflex · 3 taps — artillery strike":"Vasakul — liigu, paremal — vaata · puudutus vaenlasele — rakett / granaat · 2 puudutust — refleks · 3 puudutust — suurtükitule löök",
"Less":"Vähem",
"More":"Rohkem",
"Enemy vehicle or structure nearby — tap it: a rocket flies.":"Vaenlase tehnika või ehitis on lähedal — puuduta seda: rakett lendab.",
"Lots of hostiles — double tap an empty spot on the right: reflex slows time down.":"Palju vaenlasi — puuduta kiiresti 2 korda tühja kohta paremal: refleks aeglustab aega.",
"Aim at the enemy cluster and tap 3 times — artillery strike.":"Sihi vaenlaste kogunemisele ja puuduta 3 korda — suurtükitule löök.",
"Left thumb — move, right thumb — look. Fires by itself when aimed at an enemy.":"Vasak pöial — liigu, parem — vaata. Sihik vaenlasel — tuli avatakse ise.",
"⇑ at the left edge — jetpack: tap to hop, hold to fly.":"⇑ vasakul serval — jetpack: puuduta hüppeks, hoia lendamiseks.",
"Old v7.2 layout":"Vana v7.2 paigutus",
"Drag a finger on the right half of the screen — a look stick appears under it.":"Vii sõrme ekraani parema poole peal — sõrme alla ilmub vaatamisjoystick.",
"Touch the left side and slide — a stick appears under your finger. Reach the green marker.":"Puuduta vasakut poolt ja libista — sõrme alla ilmub joystick. Jõua rohelise märgini.",
"Hold the \"Jet\" button at the left edge.":"Hoia vasakul serval nuppu «Jet».",
"Aim at a dummy with the right stick — your trooper fires by itself when the crosshair is on it.":"Siguta parema joystickuga mannekeenile — su jalaväelane laseb ise, kui sihik on sihtmärgil.",
"Tap the dummy on the screen — a rocket flies.":"Puuduta ekraanil mannekeeni — rakett lendab.",
"Tap the dummy — a grenade flies in an arc, right at it.":"Puuduta mannekeeni — granaat lendab kaarega otse sihtmärki.",
"Double tap an empty spot on the right quickly.":"Puuduta kiiresti 2 korda tühja kohta paremal.",
"Lite mode for weak phones: lower resolution, no shadows or distortion, half the bots and particles, 30 FPS cap; lowers the resolution by itself if FPS < 25. On by default on phones (Settings → Graphics → \"Lite mode\"; or ?lite=1 / ?lite=0 in the link).":"Kerge režiim nõrkadele telefonidele: madalam resolutsioon, ilma varjude ja moonutusteta, pooleks vähem botte ja osakesi, kuni 30 kaadrit/s; langetab ise resolutsiooni, kui FPS < 25. Telefonis vaikimisi sees (Seaded → Graafika → «Kerge režiim»; või ?lite=1 / ?lite=0 lingis).",
"Phone: new controls. Left — move, right — look (both sticks appear under your finger). Left thumb alone — \"auto\"; when the right one is used, the trooper fires by itself only while the crosshair is on an enemy. Tap an enemy — rocket or grenade, 2 taps — reflex, 3 taps — artillery strike. Auto reload. Jetpack — a button at the left edge. Bottom corners are free, minimap in the corner, hints can be closed with a cross, the objective can be collapsed. Old layout: Settings → Phone.":"Telefon: uus juhtimine. Vasakul — liigu, paremal — vaata (mõlemad joystickud ilmuvad sõrme alla). Ainult vasak sõrm — «auto»; kui parem on tegevuses, laseb jalaväelane ise ainult siis, kui sihik on vaenlasel. Puudutus vaenlasele — rakett või granaat, 2 puudutust — refleks, 3 puudutust — suurtükitule löök. Automaatne laadimine. Jetpack — nupp vasakul serval. Alumised nurgad on vabad, minikaart nurgas, vihjeid saab ristiga sulgeda, ülesande saab kokku voltida. Vana paigutus: Seaded → Telefon.",
"Hints (pop-ups and curator) — one switch in settings. Who you play as (unit or vehicle type) — \"You: …\" label in the HUD. Rifle and MG optics are transparent. The \"Arsenal\" panel is docked to the right, collapsible and switchable. \"Solo without squad\" (J) is removed. The strategist voice no longer repeats the same line. Tanks get a turret-vs-hull indicator. The cursor no longer disappears at the start of the strategy tutorial.":"Vihjed (hüpikud ja kuraator) — üks lüliti seadetes. Kes sa oled (üksus või tehnika tüüp) — silt «Sina: …» HUD-is. Automaadi ja kuulipilduja optika on läbipaistev. Paneel «Arsenal» on paremal, volditav ja välja lülitatav. Režiim «üksi ilma salgata» (J) on eemaldatud. AI-strateeg ei korda sama fraasi mitu korda järjest. Tankil on näidik, kas sihitakse torni või korpust. Kursor ei kao enam strateegia väljaõppe alguses.",
