"Voice of hints & curator":"Vihjete ja juhendaja hääl",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"Telefon: kolm joystickurežiimi. Ainult vasak — „auto\" (tugev magnet, nõrgemad kuulid). Ainult parem — sihik lülitub ise sisse, tugevam magnet, täpsem tulistamine. Mõlemad — ilma sihikuta, magnet ja täpsus väiksemad. Nupp 👁 paremal — peida/too tagasi liides.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"Telefon: strateegia on lihtsustatud — ainult insener ja hooned. Vasakul kaardid (insener, staap, kasarmu…): puudutus — kaamera lendab sinna, all on kohe näha, mida ehitada/toota. „Lahingusse\" — üleval vasakul. Armee võitleb ise. Täisstrateegia — Seaded → Telefon.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"Valdamine — kaks linnukest: „Salgad\" ja „Tehnika\" (telefonis on tehnika vaikimisi väljas — seda juhib tehisaru). Kui tehnika on väljas, siis E (telefonis — nupp paremal) oma masina kõrval — istu selle kahuri taha: masin sõidab ise, sina tulistad. Vana „oma klasside järjekord\" on jaotises „Täpsemad\". Kui valdad üksust, vastab see raadios.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"Nutikad vihjed: põhivihjed lülituvad ise välja pärast 2. käivitust, kuid mäng osutab funktsioonile, mida sa kunagi ei kasuta. Linnukesed: põhilised / edasijõudnud / harvad, eraldi — vihjete ja juhendaja hääl.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"Refleks laeb tapmistest (seeria — tugevamini). Kaaslased jäid maha või hukkusid — strateeg langetab sulle uued (kallim kui tavaline abivägi). Graafika ja heli v7.2gfx on sisse viidud: pilvedena plahvatused, suits, killud, šahtide ja kraatrite akustika. Versiooni kuupäev on nüüd tõeline.",
