"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"Taevas on portaal: üles lennates jõuad meteoriidi vastaspoolele.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"Täida strateegi käske — nende eest on kogemus kahe- ja kolmekordne.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — lülitu koheselt salgale või masinale, mis on lahinguga kõige lähemal.",
"Bullets hit hardest at medium range, 20–50 meters.":"Kuulid löövad kõige tugevamini keskmisel kaugusel, 20–50 meetrit.",
