"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"Karjäär ja salvestused ei muutu. Lahingus on sama menüü nupp „🛠 Menüü\" üleval paremal{0}.",
"New developer match":"Uus arendaja mäng",
"all unlocked, endless ore, instant build, arsenal":"kõik avatud, maaki lõputult, kohene ehitus, arsenal",
"Trainings — all 4":"Väljaõpe — kõik 4",
"PC and phone (strategy and shooter)":"Arvuti ja telefon (strateegia ja laskur)",
"Cinema: split screen":"Kino: jagatud ekraan",
"strategist bot left, shooter bot right":"vasakul robot-strateeg, paremal robot-laskur",
"Cinema: everything built":"Kino: kõik ehitatud",
"both bases built and upgraded — for footage":"mõlemad baasid ehitatud ja täiustatud — filmimiseks",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"Kinorežiim — jagatud ekraan: vasakul robot-strateeg (vaade ülalt baasile ja armeele), paremal robot-laskur esimesest isikust. Nupud all (ja klahvid S, P): „Jagatud ekraan\" ja „★ Kõik ehitatud\" — mõlemad baasid ehitatud ja täiustatud filmimiseks.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"Tuuma ja tunneleid läbi meteoriidi enam pole — meteoriit on tahke, võitlus käib ainult pinnal.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"Telefon: 👁 peidab liidese, aga jätab jetpacki, ⇆, kangid ja ülesandemarkeri. „◎ Sihik\" (ainult parem sõrm) — märgatavalt tugevam ja laiem magnet; magneti tugevus kõigile kolmele režiimile — Seaded → Juhtimine → „Täpsemad\". Sõiduki kahuri taga on nupu nimi „Maha\".",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"Väljaõpe: telefonis ainult telefoni-, arvutis ainult arvutiõppused. Kõik 4 on menüüs „🛠 Arendaja\". Arendajarežiim ja Arsenal on nüüd üks menüü (lahingus — „🛠 Menüü\" üleval paremal, arvutis F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"Graafikastiilid „Dendy (8-bit)\" ja „16-bit\": Seaded → Graafika → „Graafikastiil\" (üksikasjad — nupp ⚙). Kui FPS on mängu esimese ~10 s jooksul alla 24, lülitub Dendy ise sisse (alla 20 ja edasi — veel suurem piksel, 120 rida); ülemine teade „tavaline tagasi\" taastab tavagraafika jäädavalt. Sinu enda valik menüüs on alati tähtsam.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D-keskkonnamudelid (varemed, vrakid, kindlustused) — ainult need, mis said häid hinnanguid; laaditakse vajaduse korral internetist. Väljalülitamine: Seaded → Graafika → „Uued 3D-keskkonnamudelid\".",
