"Building: {0} — stay close":"Ehitad: {0} — püsi lähedal",
"Prone / stand up (crawl)":"Pikali / püsti (roomamine)",
"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"Ehitamine jalaväelastega: E (telefonis „Sisene\") oma ehitusplatsi juures — jalaväelane ehitab ise, lähedal olevad kaaslased aitavad. Kui insenerid on hõivatud, palub strateeg ise abi — märk „EHITUSPLATS\".",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"Strateegi märgid: strateeg paneb ⌖ vaenlase kogunemisele sinu lähedal — 8 s pärast tabab seda suurtükivägi ja lähedalolevad omad MLRS „Grad\" teevad lasu. Ka sinu enda suurtükitule löök strateegiarežiimist saab „Gradide\" toetuse.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"Relvavarud kaubakonteinerites ja kukkunud satelliitides (📦 nähtav 70 m kauguselt): E — raskekuulipilduja 90 s, süütekuulid või raketid, pluss täis granaadid. Roomamine: Ctrl — pikali / püsti (madalam, püsivam sihtimine, aga aeglane).",
"Anonymous statistics":"Anonüümne statistika",
