"\"▶ Play now\" — the first menu button: a short flight under the portal sky and straight into battle (skip with any key or a tap).":"„▶ Mängi kohe\" — menüü esimene nupp: lühike lend portaalitaeva all — ja kohe lahingusse (vahelejätmine — mis tahes klahv või puudutus).",
"Hits feel like hits: a metallic sound and sparks, a kill marker at the crosshair (headshot — yellow), a ×N streak, smooth shake from explosions, slow motion on key kills. Shake, slow motion and the hint can be turned off in Settings.":"Tabamused on tunda: metalne heli ja sädemed, hävitamismärk sihiku juures (pähe — kollane), seeria ×N, sujuv värin plahvatustest, aegluubis olulistel hävitamistel. Värinat, aegluubis ja vihjet saab Seadetes välja lülitada.",
"Match results: time, kills, best streak, ★ MVP and best squad, a match card — \"⇪ Share\", PNG or a link to the game.":"Mängu kokkuvõte: aeg, hävitatud, parim seeria, ★ MVP ja parim salk, mängukaart — „⇪ Jaga\", PNG või link mängule.",
"A \"what to do now\" hint on the left under resources: the strategist's order, a point to capture, a Swarm attack. ✕ or F7 — collapse.":"Vihje „mida nüüd teha\" vasakul ressursside all: strateegi käsk, vallutatav punkt, Sülemi pealetung. ✕ või F7 — ahenda.",
"The battle saves itself when you close or hide the tab — \"⟲ Continue\" in the menu.":"Lahing salvestub ise, kui vahekaardi sulged või peidad — menüüs „⟲ Jätka\".",
"v7.5 stays in the \"🕘 Game version\" menu in case you prefer it. Anonymous statistics (no names or e-mail) are now sent; turn off in Settings.":"Versioon v7.5 jäi menüüsse „🕘 Mängu versioon\" — kui uus ei meeldi. Anonüümset statistikat (ilma nimede ja e-postita) nüüd saadetakse; väljalülitamine — Seadetes.",
"\"Play now\", hit feedback, match results with a share card, \"what to do\" hint, autosave":"„Mängi kohe\", tabamuste tagasiside, mängu kokkuvõte jagamiskaardiga, vihje „mida teha\", automaatsalvestus",
"and older: v7.5, v7.4, milestones v1–v7.0":"ja vanemad: v7.5, v7.4, verstapostid v1–v7.0",
"New in v7.6":"Uut versioonis v7.6",
"NEW IN v7.6":"UUT VERSIOONIS v7.6",
"Choose your faction before a match: the \"Consortium\" (heavy power-armoured infantry, armour and artillery) or the \"Swarm\" (speed, drone packs, heavy shots with distortion). The AI plays the other one. The choice is remembered.":"Fraktsiooni valik enne mängu: „Konsortsium\" (raske jalavägi jõurüüs, soomus ja suurtükivägi) või „Sülem\" (kiirus, droonide parved, rasked lasud moonutusega). Tehisaru mängib teise eest. Valik jäetakse meelde.",
"Each faction has its own vehicles and uniques: the Consortium — the \"Rhino\" tank and \"Ceramite plates\", the Swarm — the \"Drone pack\" and \"Phase jetpacks\". Balance checked with bot matches.":"Igal fraktsioonil on oma tehnika ja unikaalsed asjad: Konsortsiumil — tank \"Rinoceronte\" ja „Keraamilised plaadid\", Sülemil — „Droonide parv\" ja „Faasilised rakettseljakotid\". Tasakaal on kontrollitud robotite mängudega.",
"Explosion craters: artillery, rockets and tank cannons dig pits into the meteor — you can walk and drive through them and take cover inside.":"Plahvatuslehtrid: suurtükid, raketid ja tankikahurid kaevavad meteoriiti auke — neist saab läbi kõndida ja sõita ning nende sees varjuda.",
"Third-person view for troopers (V, remembered; on the phone — Controls) and a smooth vehicle camera with a marker where the cannon will hit.":"Kolmanda isiku vaade jalaväelasele (V, jääb meelde; telefonis — Juhtimine) ja sujuv tehnika kaamera märgiga, kuhu kahur tabab.",
"v7.6 stays in the \"🕘 Game version\" menu in case you prefer it.":"v7.6 jääb menüüsse \"🕘 Mängu versioon\" juhuks, kui eelistad seda.",
"Consortium / Swarm factions with a choice before the match, explosion craters, third-person view":"Konsortsiumi / Sülemi fraktsioonid koos valikuga enne mängu, plahvatuslehtrid, kolmanda isiku vaade",
"and older: v7.6, v7.5, milestones v1–v7.0":"ja vanemad: v7.6, v7.5, verstapostid v1–v7.0",
