"Anomaly ahead! The vein is singing — go around!":"Anomaalia ees! Soon laulab — mine mööda!",
"Hear that hum? A singing vein. Keep clear!":"Kuulete seda undamist? Laulev soon. Hoidke eemale!",
"Anomaly! The air is swirling — a whirlpool, go around!":"Anomaalia! Õhk keerleb — see on Küür, mine mööda!",
"Rocks floating in the air… A whirlpool! Stay out!":"Kivid hõljuvad õhus… Küür! Ära mine sinna!",
"Anomaly ahead — it is crackling with current!":"Anomaalia ees — praksub voolust!",
"Rods and lightning — a Crackler. It loves armour!":"Vardad ja välgud — Praksataja. Soomust ta armastab!",
"Anomaly! The ground shimmers with heat — a Brazier!":"Anomaalia! Maa väriseb kuumusest — Hõõgkorv!",
"Careful, a Brazier underfoot!":"Ettevaatust, jalge all on Hõõgkorv!",
"Anomaly — green mist! Acid, hold your breath!":"Anomaalia — roheline udu! Hape, hoia hinge kinni!",
"The mist is drifting our way, go around!":"Udu roomab meie poole, mine mööda!",
