"Ha! An enemy walked right into the anomaly!":"Ha! Vaenlane astus otse anomaaliasse!",
"Got him! Lure them into anomalies!":"Said ta kätte! Meelita neid anomaaliatesse!",
"Beautiful zap! One less tin can.":"Kenasti pauhtas! Üks plekkpurk vähem.",
"The anomaly got me!":"Anomaalia sai mind kätte!",
