"They say veins hide artifacts. Only first the vein sings…":"Räägitakse, et soontes peituvad artefaktid. Aga kõigepealt soon laulab…",
"Throw a bolt first, then walk. Old habit.":"Viska kõigepealt polt, siis mine. Vana komme.",
