" — close":" — sulge",
"Supply drop":"Varustuskast",
"Drops a crate near your forces: ammo, grenades, rockets, weapon parts, a repair kit.":"Heidab kasti sinu jõudude lähedale: padrunid, granaadid, raketid, relvaosad, remondikomplekt.",
"\"Grad\" rocket strike":"\"Gradi\" raketilöök",
"16 rockets over a wide area after 3 seconds — faster and wider than artillery.":"16 raketti suurele alale 3 sekundi pärast — kiiremini ja laiemalt kui suurtükiväe tuli.",
"Support: crate, recon, \"Grad\", artillery (then 1–4)":"Toetus: kast, luure, \"Grad\", suurtükitule löök (siis 1–4)",
"WARNING: Swarm \"Grad\" incoming on your area!":"TÄHELEPANU: Sülemi \"Grad\" sihib teie piirkonda!",
"Warning! Rocket salvo on our position!":"Tähelepanu! Raketisalv meie positsioonile!",
"take the supply crate":"võta varustuskast",
"Anomalies on the meteor (wave 1): the \"Singing Vein\" — a glowing green crystal that hums and strikes everyone nearby with rhythmic pulses; the \"Whirlpool\" pulls and slams, the \"Crackler\" arcs between rods, the \"Brazier\" bursts into flame underfoot, the \"Acid mist\" and the \"Lens\" (bends bullets and your view) drift around.":"Anomaaliad meteoriidil (laine 1): \"Laulev Soon\" — helendav roheline kristall, mis undab ja lööb rütmiliste impulssidega kõiki lähedalolijaid; \"Maelström\" tõmbab ja virutab, \"Praksataja\" lööb välke varraste vahel, \"Hõõgkorv\" lööb jalge all leekidesse, \"Happeudu\" ja \"Lääts\" (painutab kuule ja pilti) triivivad ringi.",
"You can feel anomalies in advance (hum, glow, heat haze). Discharge one with a grenade, a rocket or a bolt (E near it): it goes dormant and sometimes leaves an artifact with a plus and a minus. Your squad warns over the radio, and enemies (and friends) sometimes blunder in — lure them!":"Anomaaliaid tunneb ette (undamine, hõõgus, kuumahelendus). Tühjenda see granaadi, raketi või poldiga (E selle juures): see jääb magama ja jätab vahel artefakti, millel on pluss ja miinus. Salk hoiatab raadios ning vaenlased (ja omad) satuvad anomaaliasse vahel ise — meelita neid!",
"Support for command points: 4 in battle (📡 on the phone) — supply drop, recon scan, \"Grad\" rocket strike, artillery at the crosshair. The strategist sees anomalies on the map only after a scan.":"Toetus käsupunktidega: 4 võimalust lahingus (telefonis 📡) — varustuskast, luureskaneering, \"Gradi\" raketilöök, suurtükitule löök sihikule. Strateeg näeb kaardil anomaaliaid alles pärast skaneerimist.",
"Supply crates in ruins of old expeditions, near the HQs and next to finished buildings: ammo, grenades, rockets, weapon parts (they unlock attachments).":"Varustuskastid vanade ekspeditsioonide varemetes, staapide juures ja valmisehitatud hoonete kõrval: padrunid, granaadid, raketid, relvaosad (need avavad lisavarustuse).",
"v7.7 stays in the \"🕘 Game version\" menu. Anomalies can be turned off in Settings.":"v7.7 jääb menüüsse \"🕘 Mängu versioon\". Anomaaliad saab Seadetes välja lülitada.",
"Anomalies (the \"Singing Vein\" and 5 more), discharge with a bolt or grenade, artifacts, support calls for CP, supply crates":"Anomaaliad (\"Laulev Soon\" ja veel 5), tühjendamine poldi ja granaadiga, artefaktid, toetus käsupunktide eest, varustuskastid",
"and older: v7.7, v7.6, milestones v1–v7.0":"ja vanemad: v7.7, v7.6, verstapostid v1–v7.0",
"New in v7.8":"Uut versioonis v7.8",
"NEW IN v7.8":"UUT VERSIOONIS v7.8",
"Close":"Sulge",
"Anomalies on the meteor":"Anomaaliad meteoriidil",
"☰ in the corner opens the pause menu: Resume, Restart, Training, Graphics, Settings, Main menu (with confirmation). Phone: ☰ at the top right (battle actions — the \"⚡ Actions\" tile); PC: the \"☰ Menu\" button at the top right or Esc.":"☰ nurgas avab pausimenüü: Jätka, Alusta uuesti, Väljaõpe, Graafika, Seaded, Peamenüü (kinnitusega). Telefon: ☰ üleval paremal (lahingutegevused — paan \"⚡ Tegevused\"); arvuti: nupp \"☰ Menüü\" üleval paremal või Esc.",
"Graphics are always normal by default — Dendy only if you pick it: the \"Graphics: Normal / Dendy (8-bit) / 16-bit\" switch is right in the main menu and the pause menu. If the game lags badly, a tip with a \"Turn on Dendy\" button appears.":"Graafika on vaikimisi alati tavaline — Dendy ainult sinu valikul: lüliti \"Graafika: Tavaline / Dendy (8-bitine) / 16-bitine\" on otse peamenüüs ja pausis. Kui mäng väga kokku jookseb, ilmub vihje nupuga \"Lülita Dendy sisse\".",
"Phone and tablet: the \"✋\" action button on the right appears only when there is something to do nearby — \"Take\" (cache, crate), \"Board\" (vehicle, turret, gun), \"Build\", \"Get off\", \"Bolt\" at an anomaly. You can also just tap the highlighted object.":"Telefon ja tahvel: tegevusnupp \"✋\" paremal ilmub ainult siis, kui läheduses on midagi teha — \"Võta\" (varjukoht, kast), \"Istu\" (tehnika, kahurtorn, kahur), \"Ehita\", \"Maha\", \"Polt\" anomaalia juures. Võid ka lihtsalt puudutada esiletõstetud eset.",
"Phone, strategy: hold a finger ~0.3 s (the phone buzzes, a yellow ring appears) and drag — a selection box; a normal swipe moves the camera. There is also the \"Box\" button on the right; in the training the \"Box\" step also accepts tapping a squad.":"Telefon, strateegia: hoia sõrme ~0,3 s (telefon värises, ilmub kollane ring) ja lohista — valikuraam; tavaline pühkimine liigutab kaamerat. Paremal on ka nupp \"Raam\"; õppetunnis arvestab sammu \"Raam\" ka salga valimine puudutusega.",
"Phone: tiny buttons are easier to hit, the 📡 support list is bigger, strategy panels no longer cover the pause and results screens. v7.8 stays in the \"🕘 Game version\" menu.":"Telefon: väikesed nupud on kergemini tabatavad, 📡 toetusnimekiri on suurem, strateegiapaneelid ei kata enam pausi- ega tulemuste ekraani. v7.8 jääb menüüsse \"🕘 Mängu versioon\".",
"☰ menu on phone and PC, no auto-Dendy, \"✋\" button on touch, box selection on phone":"Menüü ☰ telefonis ja arvutis, ilma automaatse Dendyta, nupp \"✋\" puuteekraanil, raamiga valik telefonis",
"16-bit":"16-bitine",
"Lagging? Try the Dendy graphics — they are lighter.":"Veab? Proovi Dendy graafikat — see on kergem.",
"Turn on Dendy":"Lülita Dendy sisse",
