"The Commander mode is not in the game yet":"Režiimi \"Komandör\" pole mängus veel",
"Commander · soon":"Komandör · varsti",
"Commander — still in development":"Komandör — alles arenduses",
"Pause: resume, restart, training, graphics, settings, main menu":"Paus: jätka, uuesti, väljaõpe, graafika, seaded, peamenüü",
"Menu: pause, restart, training, graphics, settings":"Menüü: paus, uuesti, väljaõpe, graafika, seaded",
"Hold a finger on the ground ~0.3 s — the phone buzzes and a yellow ring appears — then drag without lifting: a box appears. Or use the \"Box\" button on the right. Simply tapping a squad also works.":"Hoia sõrme maas ~0,3 s — telefon väriseb ja ilmub kollane ring — ning lohista seejärel lahti laskmata: tekib raam. Või kasuta nuppu \"Raam\" paremal. Töötab ka salga lihtne puudutamine.",
"Full screen on iPhone: \"Share\" ⬆ → \"Add to Home Screen\" — the game opens without the Safari bars.":"Täisekraan iPhone'is: \"Jaga\" ⬆ → \"Lisa avaekraanile\" — mäng avaneb ilma Safari paneelideta.",
"Open portal-meteor.pages.dev for that.":"Selleks ava portal-meteor.pages.dev.",
"Tap — select · tap ground — move · hold — command menu · hold and drag — box · 2 fingers — zoom":"Puudutus — vali · puudutus maale — mine · hoia — käskude menüü · hoia ja lohista — raam · 2 sõrme — suum",
"Robo-ninja":"Robo-ninja",
"Assassin hero: blink-dashes, katana, shurikens. Teleports through enemy zones on her own and cuts robots apart. 1 per side.":"Mõrvarkangelanna: hoogsad teleportatsioonid, katana, shurikenid. Hüppab ise läbi vaenlase tsoonide ja lõikab robotid tükkideks. 1 poole kohta.",
"Shadow protocol":"Protokoll \"Vari\"",
"Research: unlocks the robo-ninja in the Barracks. Requires a finished Mech factory.":"Uuring: avab Kasarmus robo-ninja. Vajab valmis Mehhitehast.",
"Hero (1 per side): teleports through enemy zones on her own and cuts robots apart; possess her to play manually.":"Kangelanna (1 poole kohta): teleporteerub ise läbi vaenlase tsoonide ja lõikab robotid tükkideks; Haldama teda käsitsi mängimiseks.",
"is ready. She works on her own (AUTO) — possess her to play manually":"on valmis. Töötab ise (AUTO) — haldaks teda, et mängida käsitsi",
