"⚔ NINJA DUEL! Block right before a hit to parry, blink to dodge. Watch for the wind-up flash":"⚔ NINJADE DUELL! Blokeeri vahetult enne lööki — see on tõrje, vilksatus — põiklemine. Jälgi hoovõtu sähvatust",
"The two ninjas have met in a duel!":"Kaks ninjat on duellis kokku saanud!",
