"✶ AUTO: she hops through enemy zones and cuts on her own. Stick / WASD pauses it for 1.5 s":"✶ AUTO: hüppab ise läbi vaenlase tsoonide ja lõikab. Juhtkang / WASD — paus 1,5 s",
"✶ Manual: tap an enemy — dash & cut, swipe — slash, 🛡 — block":"✶ Käsitsi: puudutus vaenlasele — kihutus ja löök, pühkimine — vise, 🛡 — blokk",
"✶ Manual: LMB — katana, RMB — block, Shift — blink, Q — shurikens, G — teleport":"✶ Käsitsi: hiire vasak nupp — katana, hiire parem nupp — blokk, Shift — vilksatus, Q — shurikenid, G — teleport",
"✶ Ninja: tap an enemy — dash & cut, swipe on the right — slash, ● — strike, 🛡 — block (timed = parry), ⇑ — blink, ✦ — shurikens, ◎ — teleport, AUTO — on her own":"✶ Ninja: puudutus vaenlasel — kihutus ja löök, pühkimine paremal — vise, ● — löök, 🛡 — blokk (õigel ajal = tõrje), ⇑ — vilksatus, ✦ — shurikenid, ◎ — teleport, AUTO — tegutseb ise",
"✶ Ninja: LMB — katana (hold — heavy cut), RMB — block (timed = parry), Shift/Z — blink, Q — shurikens, G — teleport to the crosshair, jump in the air — double jump / wall-run, {0} — AUTO":"✶ Ninja: hiire vasak nupp — katana (hoia — raske löök), hiire parem nupp — blokk (õigel ajal = tõrje), Shift/Z — vilksatus, Q — shurikenid, G — teleport sihikule, hüpe õhus — topelthüpe / seinajooks, {0} — AUTO",
