"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Raadio Portal Meteor: 100+ EDMITRY lugu otse mängus — nupp 📻 (arvutis: klahv 5, [ ] — lugu). Muusika laetakse võrgust ega koorma mängu; helitugevus ja automaatkäivitus Seadetes, lisaks link \"Kuula Spotifys\".",
