"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"📻 paremal — Raadio Portal Meteor: EDMITRY muusika lahingu ajal.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Raadio Portal Meteor: EDMITRY muusika lahingu ajal. [ ] — lugu.",
"Radio Portal Meteor (EDMITRY): volume":"Raadio Portal Meteor (EDMITRY): helitugevus",
"Radio: start by itself in battle":"Raadio: käivitu lahingus ise",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"Robo-ninja: küborg katanaga. Avaneb Kasarmus uuringuga \"Varjuprotokoll\" (vaja mehhitehast). Teleporteerub ise vaenlase tsoonidesse, lõikab vaenlased tükkideks (verd pole — sädemed), kihutab, heidab shurikeneid, duellitseb vaenlase ninjaga. Võta ta üle — AUTO-režiim või käsitsi juhtimine (telefonis oma nupud).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Raadio Portal Meteor: 103 EDMITRY lugu otse mängus. Klahv 5 (muudetav), telefonis — ☰ → Seaded → Heli. Helitugevus ja \"käivitu lahingus ise\" on seadetes; muusika vaibub plahvatuste ja raadiohääle ajaks.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"Uued keeled: usbeki ja tadžiki — täielikult; hiina, hispaania, portugali — osaliselt. Uus keelevalik menüüs \"Uue mängu\" kõrval.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"Telefon: \"peida ikoonid\" 👁 koondab ülejäänud nupud korralikuks tulbaks parema serva äärde; püstiasend enam ei kattu; iPhone — mäng ei satu vastuollu Safari žestidega ja \"Jaga → Lisa avaekraanile\" käivitab selle täisekraanil.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"Versioonist v7.8.1: ☰ nurgamenüü (paus, otsast peale, väljaõpe, graafika), automaatset Dendyt pole, ✋ tegevusnupp telefonis. v7.8.1 ja v7.8 jäid menüüsse \"🕘 Mängu versioon\".",
