"Assembly hall":"Koostetsehh",
"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"Konsortsium. Lahingu 12:00-st. Siin koostatakse ülirasket tanki \"Bastion\" (üks armee kohta).",
"Incubator":"Inkubaator",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"Sülem. Lahingu 12:00-st. Siin kasvab kõndur \"Lõikaja\" (üks armee kohta).",
"Super-heavy tank \"Bastion\"":"Üliraske tank \"Bastion\"",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"Konsortsium. Boss: 15000 vastupidavust, kahur, 2 kuulipildujat, raketid. Väga aeglane. Nõrk koht — tagumik. Üks armee kohta.",
"Walker \"Reaper\"":"Kõndur \"Lõikaja\"",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"Sülem. Boss: 12500 vastupidavust, moonutuskiir, tammumine. Astub üle piirete. Nõrk koht — tuum kõhu all. Üks armee kohta.",
"Limit: 1 per army":"Limiit: 1 armee kohta",
