"Warning! The enemy is assembling the {0}. Find and destroy the plant before it is too late.":"Tähelepanu! Vastane koostab üksust {0}. Leia ja hävita tsehh, enne kui hilja on.",
"⚠ WARNING: the enemy {0} is on the battlefield!":"⚠ TÄHELEPANU: vastase {0} on lahinguväljal!",
