"Strip: ⟳ to rotate, or drag from the target along the run":"Riba: ⟳ pööramiseks või lohista sihtmärgilt lennusuunas",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"Riba: hiirerull või R pööramiseks või lohista hiirega sihtmärgilt lennusuunas",
"Into the tunnel: {0} vehicle(s)":"Tunnelisse: {0} masinat",
"Light and medium vehicles go into the nearest open tunnel":"Kerged ja keskmised masinad lähevad lähimasse avatud tunnelisse",
"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"Sülem. Salgad 70 m raadiuses tunnelaugust (ja valitud salgad) ning valitud kerged/keskmised masinad (\"Jackal\", \"Hammer\", \"Grad\") liiguvad läbi tunneli. Või: vali ja hiire parem nupp/puudutus augule.",
"Air strikes":"Õhurünnakud",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"Vaipbombardeering ja napalm: sihtimine, riba pööramine, vaenlase hoiatus, väljakutse lahingust",
"Terrain and lakes":"Maastik ja järved",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"Laava põletab, jää libiseb, metaan plahvatab tulest, kaljuangaar on kate",
"Swarm: tunnels":"Sülem: tunnelid",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"Mängid Sülemiga: tunnelauk, väljapääs kuni 220 m, tolmuhoiatus, salgad ja masinad tunnelisse",
