"Bosses":"Bossid",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"\"Bastion\" ja \"Lõikaja\": alates 12:00 (siin vahele jäetud), tehas, kokkupanek, käsk, nõrgad kohad, valdamine",
