"Veterancy carries over between battles. A squad earns XP (infantry 1, building 2, vehicle 3), levels, stars and perks. Veterans deploy first in a new battle. A lost squad loses everything and joins the Fallen.":"Veteranistaatus säilib lahingute vahel. Salk kogub kogemust (jalavägi 1, hoone 2, tehnika 3), saab tasemeid, tähti ja perke. Uues lahingus asuvad veteranid esimestena ritta. Hukkunud salk kaotab kõik ja läheb langenute hulka.",
