"Consortium: a concrete section in front of the squad for 40 s.":"Konsortsium: betoonilõik salga ees 40 s.",
"No squads to command — order a squad":"Käsutada pole salku — telli salk",
"Commander: {0}. LMB — move / attack, 1–4 — abilities, Tab — next squad, double-click a trooper — fight, P — strategy":"Komandör: {0}. hiire vasak nupp — liigu / ründa, 1–4 — oskused, Tab — teine salk, 2× sõduril — lahingusse, P — strateegia",
"Tap — move/attack, double-tap a trooper — fight, right buttons — abilities":"Puudutus — liigu/ründa, 2× puudutus sõduril — lahingusse, parempoolsed nupud — oskused",
