"Tap a point on the map (or the same button to cancel)":"Puuduta punkti kaardil (või sama nuppu — tühistamiseks)",
"LMB — where to use · same key — at cursor · RMB / Esc — cancel":"hiire vasak nupp — kuhu rakendada · sama klahv — kursorile · hiire parem nupp / Esc — tühista",
"Tap — move / attack · double-tap a trooper — fight · drag — rotate, pinch — zoom":"Puudutus — liigu / ründa · 2× puudutus sõduril — lahingusse · lohista — pööra, näpistus — suum",
"LMB — move / attack (2× run) · double-click a trooper — fight · Tab — squad · Q/E, wheel — camera · H — hold":"hiire vasak nupp — liigu / ründa (2× — jooksuga) · 2× hiire vasak nupp sõduril — lahingusse · Tab — salk · Q/E, ratas — kaamera · H — seisa",
"Commander":"Komandör",
"Commander mode: top view of one squad, abilities 1–4":"Režiim „Komandör\": vaade ülalt ühele salgale, oskused 1–4",
"Top view of your squad: click orders, abilities 1–4.":"Vaade ülalt sinu salgale: käsud klõpsuga, oskused 1–4.",
"The third mode: top view of one squad, click orders, 4 abilities, squad switching, diving into the shooter and back":"Kolmas režiim: vaade ülalt ühele salgale, käsud klõpsuga, 4 oskust, salga vahetus, sukeldumine laskuri režiimi ja tagasi",
