"Living world: requests, hero quests, breakthrough ops":"Elav maailm: omade palved, kangelaste ülesanded, pöördeoperatsioonid",
"Living world":"Elav maailm",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"Omad paluvad abi ja tasuvad selle eest, kangelased annavad ülesandeid, veniva rinde murrab operatsioon",
"A request":"Omade palve",
"Breakthrough":"Pööre lahingus",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"Omad paluvad vahel abi: hääl raadios, kaart \"PALVE\" ja märk ✋. Salk on kinni surutud — hävita selle lähedal olevad vaenlased. Tasu: jalaväelane kapsliga baasist, relv bagi pakiruumist, laskuri koht või orbitaalkate. Ei taha — ✕ või lihtsalt ignoreeri.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"Veteranluuraja \"Öökull\" pakub ülesannet. Y — nõustu (N — keeldu). Mine märgi ★ juurde, eemalda valvurid ja seisa piloodi juures 3 s — ta liitub su salgaga.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"Rinne on kinni jooksnud — staap pakub pööret. Y — nõustu. Hoia releejaama 8 s ilma vaenlasteta läheduses: vaenlase kaart on nähtav 60 s. Generaator — vaenlase kahurtornid vaikivad 2 min. Strateegi režiimis — \"Määra salk\". Vaenlane oskab seda ka: jälgi ⚠.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"Omad paluvad abi: kaart \"PALVE\" ja märk ✋. Hävita kinnisurutud salga lähedal olevad vaenlased — saad tasu. ✕ — jäta vahele.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"Kangelane \"Öökull\" pakub ülesannet — puuduta \"Nõustu\". Mine ★ juurde, eemalda valvurid, seisa piloodi juures.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"Rinne on kinni jooksnud — puuduta \"Nõustu\" ja hoia releejaama 8 s: vaenlase kaart avaneb minutiks.",
"Pod redeploy from the base: {0} m — through the sky portal":"Üleviimine kapsliga baasist: {0} m — läbi taevaportaali",
"Pod away from the base! Hold on — exit over the target.":"Kapsel läks baasist teele! Hoidke kinni — väljumine sihtmärgi kohal.",
"Landed at the objective!":"Dessant sihtmärgi juures!",
"LAUNCH FROM BASE":"START BAASIST",
"LANDING":"MAANDUMINE",
"REDEPLOY":"ÜLEVIIMINE",
"Steel fluff stuck to you — corrodes armour −2/s. Stand still 3 s out of combat or find an engineer":"Teraskohev kleepus külge — sööb soomust −2/s. Seisa 3 s lahingust eemal või mine insenerile",
"An engineer brushed the fluff off":"Insener puhastas kohevi ära",
"The fluff fell off — armour is safe":"Kohev varises maha — soomus on terve",
"The firefly swarm scattered by the blast":"Jaaniussisülem hajus plahvatusest laiali",
"STEEL FLUFF −2/s · stand still 3 s or find an engineer":"TERASKOHEV −2/s · seisa 3 s lahingust eemal või mine insenerile",
"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"Lefty konvoi on valmis: kaks \"Šaakalit\". Püsi lähedal — nad ootavad sind",
"The convoy is waiting for you":"Konvoi ootab sind",
"Ambush! Cover the Jackals!":"Varitsus! Kata \"Šaakaleid\"!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"konvoi jõudis kohale ({0} 2-st)! +2 KP, +150 maaki, \"Šaakalid\" on sinu omad",
"The parts are delivered! Thanks, commander.":"Detailid on kohal! Aitäh, komandör.",
"Show tips again":"Näita vihjeid uuesti",
"Reset":"Lähtesta",
"Sure? Tap again":"Kindel? Puuduta uuesti",
"Done":"Valmis",
"Tips and lessons will show again":"Vihjed ja õppetunnid kuvatakse uuesti",
"Steel fluff":"Teraskohev",
"Rootwalker":"Juurekäija",
"Firefly swarm":"Jaaniussisülem",
"Steel dandelions — Steel fluff! It sticks and eats armour!":"Teraspibulilled — Teraskohev! Kleepub külge ja sööb soomust!",
"Fluff in the air — keep out of the meadow and away from the infected!":"Kohev lendab — ära mine heinamaale ja hoidu nakatunutest!",
"fluff blown away, dormant for 25 s · +0.5 CP":"kohev puhuti minema, heinamaa magab 25 s · +0.5 KP",
"My crew is hauling parts to point {0}. Escort the column — there may be an ambush.":"Mu mehed vedavad detaile punkti {0}. Saada kolonn — teel võib varitseda vaenlane.",
